[{"q":"إذا كان سعر 3 أقلام 21 ريالًا، فما سعر 5 أقلام من النوع نفسه؟","o":["35 ريالًا","28 ريالًا","30 ريالًا","42 ريالًا"],"a":1},{"q":"اشترت مريم 4 دفاتر بمبلغ 32 ريالًا. كم تدفع مقابل 3 دفاتر مماثلة؟","o":["21 ريالًا","24 ريالًا","28 ريالًا","30 ريالًا"],"a":2},{"q":"ثمن علبتي عصير 12 ريالًا. كم ثمن 5 علب من النوع نفسه؟","o":["24 ريالًا","36 ريالًا","30 ريالًا","18 ريالًا"],"a":3},{"q":"ثمن 6 ممحاوات 18 ريالًا. كم ثمن 4 ممحاوات؟","o":["9 ريالات","15 ريالًا","24 ريالًا","12 ريالًا"],"a":4},{"q":"اشترى خالد 5 تفاحات بمبلغ 25 ريالًا. كم ثمن 8 تفاحات بالسعر نفسه؟","o":["40 ريالًا","35 ريالًا","45 ريالًا","30 ريالًا"],"a":1},{"q":"أربع تذاكر للحافلة ثمنها 28 ريالًا. كم ثمن 6 تذاكر؟","o":["35 ريالًا","42 ريالًا","48 ريالًا","36 ريالًا"],"a":2},{"q":"ثلاث قطع بسكويت ثمنها 12 ريالًا. كم ثمن 5 قطع؟","o":["15 ريالًا","24 ريالًا","20 ريالًا","25 ريالًا"],"a":3},{"q":"خمس زجاجات ماء ثمنها 20 ريالًا. كم ثمن زجاجتين؟","o":["10 ريالات","12 ريالًا","6 ريالات","8 ريالات"],"a":4},{"q":"مع علي 30 ريالًا، واشترى 3 أقلام ثمن القلم 6 ريالات. كم بقي معه؟","o":["12 ريالًا","18 ريالًا","24 ريالًا","10 ريالات"],"a":1},{"q":"مع سارة 50 ريالًا. اشترت كتابًا بـ18 ريالًا وعلبة ألوان بـ12 ريالًا. كم بقي معها؟","o":["30 ريالًا","20 ريالًا","22 ريالًا","18 ريالًا"],"a":2},{"q":"هناك 4 صناديق، وفي كل صندوق 6 كرات. كم كرة في الصناديق كلها؟","o":["18 كرة","20 كرة","24 كرة","30 كرة"],"a":3},{"q":"في 3 سلال، كل سلة فيها 5 برتقالات. أكل الأطفال 4 برتقالات. كم بقي؟","o":["9 برتقالات","13 برتقالة","12 برتقالة","11 برتقالة"],"a":4},{"q":"في حقيبتين 8 كتب في كل حقيبة. أُهديت 5 كتب منها. كم كتابًا بقي؟","o":["11 كتابًا","13 كتابًا","8 كتب","16 كتابًا"],"a":1},{"q":"تدخر ليلى 4 ريالات كل يوم. كم تدخر في 5 أيام؟","o":["16 ريالًا","20 ريالًا","24 ريالًا","25 ريالًا"],"a":2},{"q":"في حافلة 20 راكبًا. صعد 7 ركاب ونزل 3. كم راكبًا صار فيها؟","o":["30 راكبًا","26 راكبًا","24 راكبًا","23 راكبًا"],"a":3},{"q":"عمر أخي 8 سنوات، وأختي أكبر منه بـ3 سنوات. كم عمر أختي؟","o":["10 سنوات","12 سنة","5 سنوات","11 سنة"],"a":4},{"q":"كتاب فيه 24 صفحة. قرأت 7 صفحات صباحًا و9 مساءً. كم صفحة بقيت؟","o":["8 صفحات","10 صفحات","9 صفحات","16 صفحة"],"a":1},{"q":"بدأت حصة في الساعة 8 صباحًا وانتهت بعد 3 ساعات. متى انتهت؟","o":["10 صباحًا","11 صباحًا","12 ظهرًا","9 صباحًا"],"a":2},{"q":"الساعة الآن الثانية ظهرًا. كم تصبح بعد ساعة ونصف؟","o":["الثالثة عصرًا","الرابعة عصرًا","الثالثة والنصف عصرًا","الثانية والنصف ظهرًا"],"a":3},{"q":"كم دقيقة في ساعتين ونصف؟","o":["120 دقيقة","180 دقيقة","130 دقيقة","150 دقيقة"],"a":4},{"q":"ما العدد التالي في السلسلة: 2، 4، 6، 8، ...؟","o":["10","9","12","11"],"a":1},{"q":"ما العدد التالي في السلسلة: 3، 6، 9، 12، ...؟","o":["16","15","18","14"],"a":2},{"q":"عدد إذا أخذت نصفه كان 9. ما هذا العدد؟","o":["15","16","18","20"],"a":3},{"q":"رُتبت الكراسي في 3 صفوف، في كل صف 7 كراسٍ. كم كرسيًا؟","o":["24 كرسيًا","18 كرسيًا","20 كرسيًا","21 كرسيًا"],"a":4},{"q":"مع هناء 9 ملصقات، ومع أحمد 4 ملصقات أكثر منها. كم ملصقًا مع أحمد؟","o":["13 ملصقًا","12 ملصقًا","5 ملصقات","14 ملصقًا"],"a":1},{"q":"قُسمت 16 حبة حلوى بالتساوي على 4 أطفال. كم حبة لكل طفل؟","o":["3 حبات","4 حبات","5 حبات","6 حبات"],"a":2},{"q":"قُسمت فطيرة إلى 8 قطع، وأُكلت 3 قطع. كم قطعة بقيت؟","o":["6 قطع","4 قطع","5 قطع","3 قطع"],"a":3},{"q":"طول شريط 20 مترًا، وقصصنا منه 5 أمتار. كم مترًا بقي؟","o":["10 أمتار","25 مترًا","12 مترًا","15 مترًا"],"a":4},{"q":"وضعنا 3 كراسٍ حول كل طاولة من 4 طاولات. كم كرسيًا احتجنا؟","o":["12 كرسيًا","7 كراسٍ","9 كراسٍ","16 كرسيًا"],"a":1},{"q":"على 5 أشجار 3 عصافير لكل شجرة، ثم طار عصفوران. كم عصفورًا بقي؟","o":["15 عصفورًا","13 عصفورًا","12 عصفورًا","10 عصافير"],"a":2},{"q":"يقرأ سامي صفحتين كل يوم. كم صفحة يقرأ في 6 أيام؟","o":["8 صفحات","14 صفحة","12 صفحة","16 صفحة"],"a":3},{"q":"عمر يزن 7 سنوات وعمر أخيه 10 سنوات. ما الفرق بين عمريهما؟","o":["2 سنتان","4 سنوات","17 سنة","3 سنوات"],"a":4},{"q":"سعة الزجاجة لتران. كم لترًا في 4 زجاجات ممتلئة مماثلة؟","o":["8 لترات","6 لترات","10 لترات","12 لترًا"],"a":1},{"q":"لدينا 12 بيضة، ونضع 6 بيضات في كل علبة. كم علبة نحتاج؟","o":["3 علب","علبتان","4 علب","6 علب"],"a":2},{"q":"كم حذاءً يرتديه 6 أطفال إذا كان كل طفل يرتدي حذاءين؟","o":["6 أحذية","10 أحذية","12 حذاءً","8 أحذية"],"a":3},{"q":"لأب 4 أبناء ذكور، ولكل واحد منهم أخت واحدة هي الأخت نفسها. كم عدد الأبناء والبنات معًا؟","o":["8 أطفال","4 أطفال","6 أطفال","5 أطفال"],"a":4},{"q":"في طبق 2 برتقالة و3 تفاحات و4 موزات. كم ثمرة فيه؟","o":["9 ثمرات","8 ثمرات","10 ثمرات","7 ثمرات"],"a":1},{"q":"إذا كان اليوم الأربعاء، فما اليوم الذي يأتي بعد يومين؟","o":["الخميس","الجمعة","السبت","الأحد"],"a":2},{"q":"كنت في سباق وتجاوزت صاحب المركز الثاني. في أي مركز أصبحت؟","o":["المركز الأول","المركز الثالث","المركز الثاني","المركز الرابع"],"a":3},{"q":"في صف من 5 أطفال يقف محمد في المنتصف تمامًا. كم طفلًا يقف أمامه في الصف؟","o":["طفل واحد","3 أطفال","4 أطفال","طفلان"],"a":4}]
$easy_thinking_questions$::jsonb) AS s(q text,o jsonb,a integer)
),
owner_user AS (
  SELECT id,display_name FROM users WHERE owner AND NOT archived ORDER BY id LIMIT 1
),
inserted AS (
  INSERT INTO questions (
    company_id,category,priority,question,answer1,answer2,answer3,answer4,
    option_count,correct_answer,points,active,created_by
  )
  SELECT NULL,'أسئلة للأطفال',2,s.q,
    s.o->>0,s.o->>1,s.o->>2,s.o->>3,4,s.a,1,TRUE,u.id
  FROM source s CROSS JOIN owner_user u
  WHERE NOT EXISTS (
    SELECT 1 FROM questions old WHERE old.company_id IS NULL
      AND old.category='أسئلة للأطفال' AND old.question=s.q
  )
  RETURNING id,created_by,category,priority,question,
    answer1,answer2,answer3,answer4,correct_answer,points,active
)
INSERT INTO audit_events (
  actor_id,actor_name,scope,company_id,action,target_type,
  target_id,before_value,after_value
)
SELECT i.created_by,u.display_name,'public',NULL,'question.create',
  'question',i.id,NULL,
  jsonb_build_object('category',i.category,'priority',i.priority,
    'question',i.question,
    'options',jsonb_build_array(i.answer1,i.answer2,i.answer3,i.answer4),
    'correctAnswer',i.correct_answer,'points',i.points,'active',i.active)
FROM inserted i JOIN owner_user u ON u.id=i.created_by;
